from taf.internal.scf.tree_object import TreeObject


class Element(TreeObject):
    def __getattr__(self, item):
        if item.startswith("__"):
            return super(Element, self).__getattr__(item)

        try:
            return self._tree.item.xpath('''./node()[re:test(@name, "^{item}$")]'''.format(item=item),
                                         namespaces={'re': "http://exslt.org/regular-expressions"})[0]
        except IndexError:
            pass
